package net.officefloor.hq.app.claim;

import java.util.List;

/** A claim as the screen shows it: its amount with two decimals, its date (YYYY-MM-DD) its note, its status, its number (null when it has none)
 * and its due fixed when it was settled (null when it has none), and who opened it (null when never opened);
 * whether its person's last statement binds it, and the figure it binds it to (null: none, or n/a); the number of the
 * claim it corrects (null when it is not a correction); and the date its rounding goes by (YYYY-MM-DD: a correction's is
 * the date of the claim it corrects, else its own); and its due-by (YYYY-MM-DD), fixed when it was created; and its status log, oldest first
 * (<STATUS> by <user> on <date> due=<due>). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        String number, String due, String openedBy,
        boolean stated, String statedDue, String corrects, String roundsOn, String dueBy,
        List<String> log) {

    public static ClaimResponse from(Claim claim, List<String> log) {
        return new ClaimResponse(claim.getId(), claim.getPersonId(), claim.getAmount().setScale(2).toPlainString(),
                claim.getDate().toString(), claim.getNote(), claim.getStatus().name(), claim.getNumber(),
                claim.getDue() == null ? null : claim.getDue().setScale(2).toPlainString(), claim.getOpenedBy(),
                claim.isStated(), claim.getStatedDue() == null ? null : claim.getStatedDue().setScale(2).toPlainString(),
                claim.getCorrects(), claim.getRoundsOn().toString(), claim.getDueBy().toString(), log);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the claim's status change, once it is saved, with the claim's number when it has one;
 * a settle or approve adds the due it fixed (n/a when the grade had no rate), a reject its reason. */
public class AuditClaimStatus {
    public void audit(@Parameter String number, @Val Claim claim, PersonRepository people,
            @PathVariable("action") String action,
            @RequestParam(name = "reason", required = false) String reason,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        String person = people.findById(claim.getPersonId()).map(Person::getName).orElse("");
        String event = switch (action) {
            case "approve" -> "CLAIM_APPROVED";
            case "reject" -> "CLAIM_REJECTED";
            default -> claim.getStatus().event();
        };
        String line = ClaimAudit.line(event, claim, person, AuditUser.decode(user), number);
        if ("reject".equals(action)) {
            line += " reason=" + reason.trim();
        }
        if (claim.getStatus() == ClaimStatus.SETTLED) {
            line += " due=" + (claim.getDue() == null ? "n/a" : claim.getDue().setScale(2).toPlainString());
        }
        audit.record(line);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records the re-settle, once it is saved: the claim's line, then the due it had and the one it has now. */
public class AuditClaimResettled {
    public void audit(@Parameter Resettled resettled, @Val Claim claim, PersonRepository people,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        String person = people.findById(claim.getPersonId()).map(Person::getName).orElse("");
        audit.record(ClaimAudit.line("CLAIM_RESETTLED", claim, person, AuditUser.decode(user))
                + " old=" + shown(resettled.old()) + " new=" + shown(resettled.now()));
    }

    private static String shown(BigDecimal due) {
        return due == null ? "n/a" : due.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/**
 * Re-settles a SETTLED claim: freezes its due again at the figure it would have today as an open claim bound by no
 * statement (today's rates, grades, floor and late charge; n/a leaves it live). Only a steward re-settles, and a claim
 * dated in a closed period, or in any other status, cannot be. Returns the due it had before, for the audit.
 */
public class ApplyResettle {
    public Resettled apply(@Val Claim claim, @Val Sheet sheet, ClaimRepository repository, PersonRepository people,
            RateRepository rates, PersonGradeRepository grades, PeriodRepository periods, RoleRepository roles,
            @RequestHeader(name = "X-User", required = false) String userHeader)
            throws ClaimStatusException, ClerkLimitException {
        String user = AuditUser.decode(userHeader);
        if (periods.isClosedOn(claim.getSheetId(), claim.getDate())) {
            throw new ClaimStatusException("A claim in a closed period cannot be re-settled.");
        }
        if (!Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), user))) {
            throw new ClerkLimitException("Only a steward can re-settle a claim.");
        }
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be re-settled.");
        }
        BigDecimal old = claim.getDue();
        BigDecimal due = people.findById(claim.getPersonId())
                .map(p -> new ClaimFigures(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(claim.getSheetId()),
                        grades.gradesOf(p), sheet).openDue(claim))
                .orElse(null);
        claim.setDue(due);
        repository.saveAndFlush(claim);
        return new Resettled(old, due);
    }
}
package net.officefloor.hq.app.claim;

/** A claim's audit line: the event, sheet, user, person, amount as the screen shows it, date, and the claim's
 * number when it has one. */
public final class ClaimAudit {

    private ClaimAudit() {
    }

    public static String line(String event, Claim claim, String person, String user) {
        return line(event, claim, person, user, claim.getNumber());
    }

    static String line(String event, Claim claim, String person, String user, String number) {
        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person
                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
                + (number == null ? "" : " number=" + number);
    }
}
