import { HomeMain } from '../../slots/defs/homeMain';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { gradeOn, usePeople, type Person } from '../people/people';
import { countsLive, holdsOf, isBound, useClaims, type Claim } from '../claims/claims';
import { useSettings, type Settings } from '../roles/roles';
import { chargedOf, formatCents, rateOn, sumDue, useRates, type Rate } from './rates';

// A person's due-total: the sum of their counted claims' dues, each already rounded (a settled claim's
// frozen due, else the figure their last statement bound it to, else its live due, at least the sheet's floor; plus
// an overdue claim's late charge; each claim at the grade they had on its date) — 0.00 with nothing that counts.
// When their grade in force on the sheet's today has no rate in force then it is n/a, unless a counted claim keeps
// a figure — settled, bound, or live at another grade they had on its date, or live
// on or before the sheet's today at a rate that has ended since: then it is the sum of the figures there are. It is at most
// the sheet's cap: above it, it shows the cap and their excess the difference (n/a is not capped). Their unbound OPEN claims dated within a hold of theirs do not count. The sheet's due-total is everyone's added up, skipping n/a.
export function personDue(person: Person, claims: Claim[], rates: Rate[] | undefined, today: string | undefined,
  settings: Settings | undefined): string {
  return capped(personFigures(person, claims, rates, today, settings), settings).due;
}

/** A person's excess: how much the sum of their figures is above the sheet's cap; 0.00 when it is not (or n/a). */
export function personExcess(person: Person, claims: Claim[], rates: Rate[] | undefined, today: string | undefined,
  settings: Settings | undefined): string {
  return capped(personFigures(person, claims, rates, today, settings), settings).excess;
}

/** A sum of figures held to the sheet's cap ("" for none), and how much it was above it; n/a is not capped. */
function capped(sum: string, settings: Settings | undefined): { due: string; excess: string } {
  const cap = settings?.cap ?? '';
  if (sum === 'n/a' || cap === '' || Number(sum) <= Number(cap)) return { due: sum, excess: '0.00' };
  return { due: sumDue([cap]), excess: subtract(sum, cap) };
}

/** The difference of two two-decimal amounts, exactly. */
function subtract(a: string, b: string): string {
  const cents = (s: string) => BigInt(Math.round(Number(s) * 100));
  return formatCents(cents(a) - cents(b));
}

/** The sum of a person's figures, before the cap. */
function personFigures(person: Person, claims: Claim[], rates: Rate[] | undefined, today: string | undefined,
  settings: Settings | undefined): string {
  const mine = claims.filter((c) => c.personId === person.id && countsLive(c, holdsOf([person])));
  const grade = gradeOn(person, today);
  const kept = (c: Claim) => c.due !== null || (isBound(c) && c.statedDue !== null)
    || (!isBound(c) && (gradeOn(person, c.date) !== grade || (today !== undefined && c.date <= today)) && chargedOf(c, rates, gradeOn(person, c.date), settings, today) !== 'n/a');
  if (rateOn(rates, grade, today) === undefined && !mine.some(kept)) {
    return 'n/a';
  }
  return sumDue(mine.map((c) => chargedOf(c, rates, gradeOn(person, c.date), settings, today)));
}

function DueHeader() {
  return <th>Due</th>;
}

function PersonDue({ person }: { person: Person }) {
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  return <td data-testid="person-due-total">{personDue(person, claims.data ?? [], rates.data, today, settings.data)}</td>;
}

function ExcessHeader() {
  return <th>Excess</th>;
}

function PersonExcess({ person }: { person: Person }) {
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  return <td data-testid="person-excess">{personExcess(person, claims.data ?? [], rates.data, today, settings.data)}</td>;
}

function DueTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  if (!user || !sheet) return null;
  const total = sumDue((people.data ?? []).map((p) => personDue(p, claims.data ?? [], rates.data, today, settings.data)));
  return (
    <p>
      Due in total <strong data-testid="rollup-due-total">{total}</strong>
    </p>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 15, Component: DueHeader }),
  PersonCells.fill({ order: 15, Component: PersonDue }),
  PeopleColumns.fill({ order: 15.5, Component: ExcessHeader }),
  PersonCells.fill({ order: 15.5, Component: PersonExcess }),
  HomeMain.fill({ order: 31, Component: DueTotal }),
];
import { HomeMain } from '../../slots/defs/homeMain';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { gradeOn, usePeople, type Person } from '../people/people';
import { useSettings, type Settings } from '../roles/roles';
import { chargedOf, sumDue, useRates, type Rate } from '../rates/rates';
import { countsLive, holdsOf, isOverdue, useClaims, type Claim } from './claims';

// A person's overdue count and overdue-total: their counted claims that are overdue (OPEN or PENDING, due-by before the
// sheet's today; their unbound OPEN and PENDING claims dated within a hold of theirs do not count), and those claims' dues (with their late charge) added up, skipping n/a.
// The sheet's are everyone's added up.
export function overdueOf(person: Person, claims: Claim[], rates: Rate[] | undefined, today: string | undefined,
  settings: Settings | undefined): { count: number; total: string } {
  const held = holdsOf([person]);
  const mine = claims.filter((c) => c.personId === person.id && countsLive(c, held) && isOverdue(c, today));
  return { count: mine.length, total: sumDue(mine.map((c) => chargedOf(c, rates, gradeOn(person, c.date), settings, today))) };
}

function useOverdue() {
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  return (person: Person) => overdueOf(person, claims.data ?? [], rates.data, today, settings.data);
}

function OverdueHeader() {
  return (
    <>
      <th>Overdue</th>
      <th>Overdue total</th>
    </>
  );
}

function PersonOverdue({ person }: { person: Person }) {
  const { count, total } = useOverdue()(person);
  return (
    <>
      <td data-testid="person-overdue-count">{count}</td>
      <td data-testid="person-overdue-total">{total}</td>
    </>
  );
}

function OverdueTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const overdue = useOverdue();
  if (!user || !sheet) return null;
  const each = (people.data ?? []).map(overdue);
  return (
    <p>
      Overdue <strong data-testid="rollup-overdue-count">{each.reduce((n, o) => n + o.count, 0)}</strong>{' '}
      totalling <strong data-testid="rollup-overdue-total">{sumDue(each.map((o) => o.total))}</strong>
    </p>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 16, Component: OverdueHeader }),
  PersonCells.fill({ order: 16, Component: PersonOverdue }),
  HomeMain.fill({ order: 32, Component: OverdueTotal }),
];
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import type { Person } from '../people/people';
import { holdsOf, sumOf, useClaims } from './claims';

// A person's claimed: the sum of their OPEN, PENDING and SETTLED claims' amounts (not unbound OPEN ones dated within a hold of theirs).
function ClaimedHeader() {
  return <th>Claimed</th>;
}

function PersonClaimed({ person }: { person: Person }) {
  const claims = useClaims();
  return <td data-testid="person-claimed">{sumOf((claims.data ?? []).filter((c) => c.personId === person.id), holdsOf([person]))}</td>;
}

export const contributions = [
  PeopleColumns.fill({ order: 10, Component: ClaimedHeader }),
  PersonCells.fill({ order: 10, Component: PersonClaimed }),
];
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { usePeople } from '../people/people';
import { holdsOf, sumOf, useClaims } from './claims';

// The sheet's claimed-total: everyone's claimed added up.
function ClaimedTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const claims = useClaims();
  if (!user || !sheet) return null;
  return (
    <p>
      Claimed in total <strong data-testid="rollup-claimed-total">{sumOf(claims.data ?? [], holdsOf(people.data))}</strong>
    </p>
  );
}

export const contribution = HomeMain.fill({ order: 30, Component: ClaimedTotal });
    queryKey: periodsQueryKey(sheet ?? ''),
    queryFn: () => getJson<Period[]>(periodsPath(sheet ?? '')),
    enabled: !!sheet,
  });
}

/** The period whose dates contain a date (YYYY-MM-DD), or undefined for none. */
export function periodOn(periods: Period[] | undefined, date: string): Period | undefined {
  return (periods ?? []).find((p) => p.from <= date && date <= p.to);
}

/** A period's due-total: the dues (with any late charge) of the counted claims whose date falls in it (not a person's
 *  unbound OPEN ones dated within a hold of theirs), added up, skipping n/a; for a closed period, the one fixed when it was closed. */
export function periodDue(period: Period, people: Person[] | undefined, claims: Claim[], rates: Rate[] | undefined,
  settings: Settings | undefined, today: string | undefined): string {
  if (period.closedTotal !== null) return period.closedTotal;
  const personOf = new Map((people ?? []).map((p) => [p.id, p]));
  const held = holdsOf(people);
  return sumDue(claims
    .filter((c) => countsLive(c, held) && personOf.has(c.personId) && periodOn([period], c.date))
    .map((c) => chargedOf(c, rates, gradeOn(personOf.get(c.personId)!, c.date), settings, today)));
}

/** A person's due-total for a period: the dues (with any late charge) of their counted claims whose date falls in it
 *  (not their unbound OPEN ones dated within a hold of theirs), added up, skipping n/a; for a closed period, the one
 *  fixed when it was closed — 0.00 for a person added since. */
export function personPeriodDue(period: Period, person: Person, people: Person[] | undefined, claims: Claim[],
  rates: Rate[] | undefined, settings: Settings | undefined, today: string | undefined): string {
  if (period.closed) return period.personTotals?.[String(person.id)] ?? '0.00';
  const held = holdsOf(people);
  return sumDue(claims
    .filter((c) => c.personId === person.id && countsLive(c, held) && periodOn([period], c.date))
    .map((c) => chargedOf(c, rates, gradeOn(person, c.date), settings, today)));
}
  halfUp = false): string {
  if (c.due !== null) return c.due;
  if (isBound(c)) return c.statedDue ?? 'n/a';
  const due = dueOf(c.amount, rateOn(rates, grade, c.date), halfUp);
  return c.corrects !== null ? due : atLeast(due, floor);
}

/** A claim's due: a settled claim's frozen due, else its figure (at least the floor in force on its date) plus its
 *  late charge — the sheet's late percent in force on its date of the figure for every full 30 days it is overdue on the sheet's today, rounded like a due ("n/a" when it
 *  has no figure). A statement binds only the figure: the charge keeps following the sheet's today. A correction never
 *  takes a late charge. */
export function chargedOf(c: Claim, rates: Rate[] | undefined, grade: string, settings: Settings | undefined,
  today: string | undefined): string {
  const halfUp = roundsHalfUp(c, settings, today);
